"""Necessary geometry rows generated by the original complete-entity oracle.

The planner keeps one final cubic.  This module consumes the *same-curve*
pair evidence returned by the existing scene query; it never turns a broad
phase box or an unresolved domain into collision material.  Frozen observed
material points yield necessary inequalities, while the original complete
entity and continuous-time queries determine whether more rows are needed.

Robot geometry is the existing official fixed robot/end-effector model.  It
is reusable across tasks because its shape and fixed component relationships
do not change.  Field entities remain their original RGB-D trilinear samples
and observation support.  No task mesh or alternate collision solid is made.
"""

from dataclasses import asdict, dataclass

import coal
import numpy as np
import torch
from scipy.spatial.transform import Rotation

from manipulation.implicit_distance import CORNERS, ObservedField, PairPermission, inverse_points
from manipulation.native_field_distance import _transform
from manipulation.online_geometry import _matrices
from manipulation.planning_problem import quaternion_conjugate, quaternion_multiply, quaternion_rotate
from manipulation.resource_admission import require_host_memory
from manipulation.sampled_geometry_objective import _allowed
from manipulation.unified_solver import robot_tool_states


def _world(point, pose):
    """Place one fixed material coordinate in the calibrated world frame."""
    return pose[0] + quaternion_rotate(pose[1], pose[0].new_tensor(point))


def _local(world, pose):
    return quaternion_rotate(quaternion_conjugate(pose[1]), world - pose[0])


def native_point_value(geometry, local):
    """Original signed point distance and current closest-feature direction.

    A zero-radius Coal sphere represents a query point, not a replacement
    obstacle.  The returned normal is in the unchanged native entity frame.
    # BEGIN numerical meaning of Coal's returned closest-feature direction.
    Coal's default iterative query determines the accuracy of this direction.
    The Torch graph propagates that returned first-order direction exactly;
    it does not differentiate the iterations of the Coal distance algorithm
    or provide second derivatives through its nearest-feature selection.
    # END model distance, numerical query precision and propagation are distinct.
    """
    request, result = coal.DistanceRequest(), coal.DistanceResult()
    request.enable_signed_distance = True
    numeric = local.detach().cpu().numpy()
    value = coal.distance(geometry, _transform(np.eye(4)), coal.Sphere(0.),
        coal.Transform3s(np.eye(3), numeric), request, result)
    gradient = local.new_tensor(np.asarray(result.normal, dtype=float))
    return local.new_tensor(value) + ((local - local.detach()) * gradient).sum()


def field_point_value(field, local, *, excluded_cells=()):
    """Original supported trilinear scalar, or an explicitly inactive row.

    The scalar is a TSDF interpolant, not an invented Euclidean distance.
    ``supported=False`` keeps the geometric state unknown.  The returned zero
    is an inactive necessary inequality and is never separation evidence.
    """
    numeric = local.detach().cpu().numpy()
    values, supported, gradient, _ = field.sample(numeric[None], excluded_cells=excluded_cells)
    if not bool(supported[0]):
        return local.sum() * 0., False, False
    derivative = local.new_tensor(gradient[0])
    value = local.new_tensor(values[0]) + ((local - local.detach()) * derivative).sum()
    return value, True, bool(np.any(gradient[0] != 0.))


def occupied_material(field, local, *, excluded_cells=()):
    """Check that a point belongs to the closure of represented volume.

    A strictly negative supported value supplies occupied volume locally.
    A supported full-nonpositive cell also supplies volume, including a
    constant-zero cell.  An isolated zero surface is not enough: the original
    volume oracle records that case as unresolved rather than penetration.
    """
    local = np.asarray(local, dtype=float)
    values, supported, _, error = field.sample(local[None], excluded_cells=excluded_cells)
    if not bool(supported[0]):
        return False
    if values[0] < -error[0]:
        return True
    grid = (local - field.origin) / field.voxel_size
    base = np.floor(grid).astype(int)
    excluded = set(excluded_cells)
    for corner in CORNERS.astype(int):
        cell = base - corner
        if (np.any(cell < 0) or np.any(cell >= field.cell_shape)
                or not field.valid_cells[tuple(cell)]):
            continue
        origin = field.origin + cell * field.voxel_size
        if np.any(local < origin) or np.any(local > origin + field.voxel_size):
            continue
        # Original occupied-cell identity owns finite support exclusions.
        if excluded:
            match = np.flatnonzero(np.all(field.cells == cell, axis=-1))
            if len(match) and int(match[0]) in excluded:
                continue
        samples = field.values[tuple((cell + CORNERS.astype(int)).T)]
        if np.all(samples <= 0):
            return True
    return False


@dataclass(frozen=True)
class WitnessRow:
    """One same-clock necessary condition; all local coordinates are metres."""

    time_s: float
    progress: float
    permission_progress: float
    first: str
    second: str
    component: str
    source_status: str
    kind: str
    source: str = ""
    target: str = ""
    point_local: tuple = ()


class GeometryConstraints:
    """Generate fixed rows between bounded calls of the maintained solver.

    ``computation`` is the original full-control TrajectoryComputation, not a
    wrapper accepting reduced controls.  ``add_evidence`` consumes original
    ``_geometry_query_states`` output.  ``rows`` uses full cubic coefficients
    and returns g <= 0 in original scalar units.  Row identity and dimension
    remain unchanged throughout one SLSQP call.
    """

    def __init__(self, computation):
        self.computation = computation
        self.scene = computation.scene
        self.witnesses = []
        self._identities = set()
        self._centers = {}
        self.discoveries = []
        self.last_evaluation = {}
        self._unknown_geometries = (set() if self.scene.gripper is None else
            set(self.scene.robot_model.geometry_depending_on(self.scene.gripper.joint_names)))

    @property
    def row_count(self):
        """Fixed solver dimension until the next explicit evidence update."""
        return len(self.witnesses)

    def workspace_bytes(self, *, record_count=None):
        """Bound this component's added arrays at its actual query dimensions.

        The original task graph and dense solver are already counted by their
        owners. This component adds a second full FK batch containing base
        release anchors plus witness times. PinStates retains poses, twists,
        the pose Jacobian and both twist Jacobians. Only the larger reverse
        batch's difference from the original task reverse is added to the
        solver estimate. Scene fields and native models remain shared.
        """
        base = self.computation
        rows = self.row_count if record_count is None else int(record_count)
        if rows == 0:
            return {}
        samples = len(base.parameters) + rows
        controls, arm_joints = base.domain._curve_map.knots, len(base.joint_names)
        frames, joints = len(base.kinematics.frames), len(base.kinematics.joint_names)
        entities = len(self.scene.robot_model._geometries) + len(self.scene.owners) + 1
        # Feature transforms retain point/cross-product inputs for one reverse
        # pass. Halfspaces retain normal/bound derivatives. The scalar count
        # includes source/target poses, masks, gap, angle and detached policy
        # arrays. These bounds concern extra live arrays, not model storage.
        feature_scalars = sum(96 * len(rule.feature_points)
            + 32 * (len(rule._feature_edge_normals) + 10) + 128 for rule in self.scene.contacts)
        fields = (self.scene.background, *(owner.query for owner in self.scene.owners))
        return {
            "affine_query_arrays_and_named_states": 8 * samples * (
                4 * (controls + arm_joints) + 8 * joints + 6),
            "pinocchio_added_forward_and_saved_derivatives": 8 * samples * frames * (13 + 18 * joints),
            "entity_pose_transforms_and_matrices": 8 * samples * entities * 128,
            "finite_permission_transform_graph": 8 * samples * feature_scalars,
            # BEGIN distinguish tensor adjoints from shared Python provenance.
            "witness_scalar_graphs": rows * 8 * 128,
            "witness_records": rows * 1024,
            # END batched derivatives expand only the scalar tensor envelope.
            # A finite support exclusion makes one temporary valid-cell mask;
            # volume qualification may also compare original occupied-cell
            # identities. Point queries run serially, so only one field's
            # largest mask/index scratch is live at a time.
            "observed_field_query_scratch": max(
                field.valid_cells.nbytes + 16 * len(field.cells) for field in fields),
            "additional_largest_pinocchio_reverse": 8 * rows * (6 * frames * joints + 12 * frames + joints),
        }

    def _context(self, controls, records):
        """Reuse full FK and original relation producers at exact record times.

        The base complete query precedes added rows so all original release
        anchors remain available to the scene's differentiable release gather.
        Same-time mode sides retain their recorded progress independently of
        physical q(t); finite permission uses its own original progress value.
        """
        base = self.computation
        require_host_memory(sum(self.workspace_bytes(record_count=len(records)).values()),
            pending_existing_bytes=0, max_rss_bytes=base.max_host_rss_bytes)
        count = len(base.parameters)
        times = np.r_[base.times.detach().numpy()[0], [row["time_s"] for row in records]]
        progress = np.r_[base.progress.detach().numpy()[0], [row["progress"] for row in records]]
        permission_progress = np.r_[base.progress.detach().numpy()[0],
            [row["permission_progress"] for row in records]]
        arrays = [base.domain._curve_map.query(times / base.duration, order) for order in (0, 1)]
        q, dq = [(controls.new_tensor(row) @ controls + controls.new_tensor(offset))[None]
                 for row, offset in arrays]
        progress = controls.new_tensor(progress)[None]
        permission_progress = controls.new_tensor(permission_progress)[None]
        times = controls.new_tensor(times)[None]
        hand = (None if self.scene.gripper is None else self.scene.gripper.state(
            progress, q, base.joint_names, trajectory_time=times))
        _, _, _, links, tool, _ = robot_tool_states(problem=base.problem, scene=self.scene,
            kinematics=base.kinematics, q=q, dq=dq, joint_names=base.joint_names,
            progress=progress, times=times)
        poses, geometries = {}, {}
        for name, (frame, geometry, _, local) in self.scene.robot_model._geometries.items():
            position, quaternion = links[frame]
            local_q = Rotation.from_matrix(local[:3, :3]).as_quat()[[3, 0, 1, 2]]
            poses[f"robot/{name}"] = (position + quaternion_rotate(quaternion,
                position.new_tensor(local[:3, 3])),
                quaternion_multiply(quaternion, quaternion.new_tensor(local_q)))
            geometries[f"robot/{name}"] = geometry
        owners = self.scene._owner_poses(*tool, progress, None, {})
        for owner in self.scene.owners:
            poses[f"owner/{owner.owner_id}"] = owners[owner.owner_id]
            geometries[f"owner/{owner.owner_id}"] = owner.query
        identity = (torch.zeros_like(tool[0]), torch.zeros_like(tool[1]))
        identity[1][..., 0] = 1.
        poses["background"], geometries["background"] = identity, self.scene.background
        policies = {}
        for rule in self.scene.contacts:
            actor = tool if rule.actor == "robot" else owners[rule.actor]
            policies[rule.rule_id] = self.scene._permission(rule, actor,
                owners[rule.target_owner], permission_progress,
                None if hand is None else hand.coordinates,
                uncertain_hand=None if hand is None else hand.uncertain)[0]
        return dict(offset=count, poses=poses, geometries=geometries, policies=policies,
                    matrices={key: _matrices(value) for key, value in poses.items()},
                    hand=hand, progress=progress)

    def _permission(self, context, record, column):
        """Recreate the existing pair domain from current poses and declarations."""
        first, second = record["first"], record["second"]
        hand = context["hand"]
        if hand is not None and bool(hand.uncertain[0, column]):
            names = {name.removeprefix("robot/") for name in (first, second)
                     if name.startswith("robot/")}
            if names & self._unknown_geometries:
                return None, "unmodelled_motion"
        if first.startswith("robot/") and second.startswith("robot/"):
            return None, "active"
        actor = "robot" if first.startswith("robot/") else first.removeprefix("owner/")
        target = second.removeprefix("owner/")
        progress = record["progress"]
        attached = {owner.owner_id for owner in self.scene.owners
            if any(bool(relation.active(np.asarray(progress))) for relation in owner.attachments)}
        if target in attached and ((actor == "robot" and first[6:] in self.scene.tool_geometry_names)
                                   or actor in attached):
            return None, "internal_assembly"
        regions = []
        for rule in self.scene.contacts:
            applies = ((actor == "robot" and rule.actor == "robot" and rule.target_owner == target
                        and rule.robot_body == first[6:])
                       or (actor != "robot" and {rule.actor, rule.target_owner} == {actor, target}))
            policy = context["policies"][rule.rule_id]
            if applies and bool((policy["active"] & policy["normal_valid"])[0, column]):
                matrix = context["matrices"][f"owner/{rule.target_owner}"][0, column]
                normals = policy["normals"][0, column].detach().numpy() @ matrix[:3, :3].T
                bounds = policy["bounds"][0, column].detach().numpy() + normals @ matrix[:3, 3]
                regions.append(((normals, bounds), (normals, bounds)))
        permission = PairPermission(regions) if regions else None
        for model in self.scene._initial_support_models.values():
            relation = model.relation
            if (relation.actor == actor and relation.target_owner == target
                    and relation.interval[0] <= record["permission_progress"] < relation.interval[1]):
                permission = model.permission(context["matrices"][second][0, column], additional=permission)
        return permission, "active"

    def _native_interior_witness(self, native, native_matrix, field, field_matrix,
                                 world, permission, excluded):
        """Find actual observed material strictly inside the unchanged native solid.

        The full oracle's intersection can lie on the robot boundary.  A line
        toward the convex solid's interior stays in that solid.  Bisection
        selects a point only after the original field membership, finite
        permission and native signed query all agree.  This constructs an
        optimization witness; the oracle's classification remains unchanged.
        """
        key = id(native)
        if key not in self._centers:
            # The maintained native API gives the volume centroid of the
            # same full-dimensional convex robot solid, an interior point.
            self._centers[key] = np.asarray(native.computeCOM(), dtype=float)
        center = native_matrix[:3, :3] @ self._centers[key] + native_matrix[:3, 3]
        fraction = 1.
        proposal = np.asarray(world, float)
        while True:
            if self.scene.check_request is not None:
                self.scene.check_request()
            local = inverse_points(proposal, field_matrix)
            if (occupied_material(field, local, excluded_cells=excluded)
                    and not bool(_allowed(proposal[None], permission)[0])):
                distance = native_point_value(native, torch.as_tensor(
                    inverse_points(proposal, native_matrix), dtype=torch.float64))
                if float(distance) < 0:
                    return local
            next_proposal = np.asarray(world) + fraction * (center - world)
            if np.array_equal(next_proposal, proposal) or np.array_equal(next_proposal, world):
                return None
            proposal = next_proposal
            fraction *= .5

    def add_evidence(self, full_controls, states):
        """Add necessary rows from a completed original full-curve query.

        All confirmed intersections retain their actual times.  Other states
        contribute at most the closest available witness per entity pair.
        Selection changes optimization work only; it never claims complete
        geometry coverage.  Evidence without actual material witnesses adds
        no artificial point or direction.
        """
        records, closest = [], {}
        total = 0
        for state in states:
            for pair in state["pairs"]:
                total += 1
                entity = pair["geometry_entity_key"]
                record = {**pair, "time_s": float(state["time_s"]),
                    "progress": float(pair.get("progress", state["progress"])),
                    "permission_progress": float(pair.get("permission_progress", state["progress"])),
                    "first": entity["first"], "second": entity["second"]}
                if pair["status"] in {"unmodelled_motion", "internal_assembly"}:
                    continue
                if pair["status"] == "intersection":
                    records.append(record)
                elif pair.get("witness_first") is not None and pair.get("witness_second") is not None:
                    key = entity["first"], entity["second"]
                    rank = (float(pair.get("lower_m") or 0.), float(pair.get("upper_m") or np.inf),
                            float(state["time_s"]))
                    if key not in closest or rank < closest[key][0]:
                        closest[key] = rank, record
        records.extend(value[1] for value in closest.values())
        result = {"source_pair_records": total, "selected_pair_records": len(records),
                  "added_rows": 0, "skipped": []}
        if not records:
            self.discoveries.append(result)
            return result
        controls = torch.as_tensor(np.asarray(full_controls), dtype=torch.float64)
        with torch.no_grad():
            context = self._context(controls, records)
            for ordinal, record in enumerate(records):
                column = context["offset"] + ordinal
                first, second = record["first"], record["second"]
                permission, mode = self._permission(context, record, column)
                common = {key: record[key] for key in (
                    "time_s", "progress", "permission_progress", "first", "second", "component")}
                common["source_status"] = record["status"]
                pending = []
                if mode != "active":
                    result["skipped"].append({**common, "reason": mode})
                    continue
                if first.startswith("robot/") and second.startswith("robot/"):
                    pending.append(WitnessRow(**common, kind="native_pair"))
                elif first.startswith("robot/"):
                    world = record.get("witness_second")
                    if world is not None:
                        native, field = context["geometries"][first], context["geometries"][second]
                        native_matrix, field_matrix = (context["matrices"][key][0, column]
                                                       for key in (first, second))
                        excluded = () if permission is None else permission.excluded_second_cells
                        local = inverse_points(world, field_matrix)
                        if record["status"] == "intersection":
                            local = self._native_interior_witness(native, native_matrix, field,
                                field_matrix, np.asarray(world), permission, excluded)
                        if local is not None and occupied_material(field, local, excluded_cells=excluded):
                            pending.append(WitnessRow(**common, kind="material", source=second,
                                target=first, point_local=tuple(map(float, local))))
                else:
                    for source, target, point_key in ((first, second, "witness_first"),
                                                     (second, first, "witness_second")):
                        world = record.get(point_key)
                        if world is None:
                            continue
                        local = inverse_points(world, context["matrices"][source][0, column])
                        excluded = (() if permission is None or source != second else
                                    permission.excluded_second_cells)
                        if occupied_material(context["geometries"][source], local, excluded_cells=excluded):
                            pending.append(WitnessRow(**common, kind="material", source=source,
                                target=target, point_local=tuple(map(float, local))))
                if not pending:
                    result["skipped"].append({**common, "reason": "no_qualified_volume_material_witness"})
                for row in pending:
                    identity = (row.time_s, row.progress, row.permission_progress, row.first,
                                row.second, row.kind, row.source, row.target, row.point_local)
                    if identity not in self._identities:
                        self._identities.add(identity)
                        self.witnesses.append(row)
                        result["added_rows"] += 1
        self.discoveries.append(result)
        return result

    def rows(self, full_controls):
        """Return fixed-dimensional necessary inequalities g <= 0.

        Every signed scalar and its closest-feature direction are recomputed.
        Unknown, permitted and declared internal material have inactive zero
        rows, with their state retained separately.  They never acquire a
        positive distance or a fabricated separating normal.
        """
        if not self.witnesses:
            self.last_evaluation = {"rows": [], "active_count": 0, "inactive_count": 0}
            return full_controls.reshape(-1)[:0]
        records = [asdict(row) for row in self.witnesses]
        context = self._context(full_controls, records)
        values, reports = [], []
        for ordinal, record in enumerate(records):
            if self.scene.check_request is not None:
                self.scene.check_request()
            column = context["offset"] + ordinal
            pose = lambda key: tuple(item[0, column] for item in context["poses"][key])
            permission, mode = self._permission(context, record, column)
            zero = full_controls.sum() * 0.
            value, direction = zero, False
            if mode == "active" and record["kind"] == "native_pair":
                first, second = record["first"], record["second"]
                request, result = coal.DistanceRequest(), coal.DistanceResult()
                request.enable_signed_distance = True
                fm, sm = (context["matrices"][key][0, column] for key in (first, second))
                distance = coal.distance(context["geometries"][first], _transform(fm),
                    context["geometries"][second], _transform(sm), request, result)
                a, b = inverse_points(result.getNearestPoint1(), fm), inverse_points(result.getNearestPoint2(), sm)
                relative = _world(b, pose(second)) - _world(a, pose(first))
                # BEGIN retain the original native query's numerical semantics.
                # Coal's iterative closest features supply a local first-order
                # direction. This propagates their rigid motion through FK;
                # it is not a derivative of Coal's finite iteration algorithm.
                derivative = (relative * relative.new_tensor(np.asarray(result.normal))).sum()
                # END default Coal numerical settings remain the query authority.
                value = -(derivative.new_tensor(distance) + derivative - derivative.detach())
                direction = bool(np.any(np.asarray(result.normal) != 0.))
            elif mode == "active":
                source, target = record["source"], record["target"]
                source_field = context["geometries"][source]
                source_excluded = (() if permission is None or source != record["second"]
                                   else permission.excluded_second_cells)
                world = _world(record["point_local"], pose(source))
                if not occupied_material(source_field, record["point_local"], excluded_cells=source_excluded):
                    mode = "material_excluded_or_unsupported"
                elif bool(_allowed(world.detach().numpy()[None], permission)[0]):
                    mode = "permitted"
                else:
                    coordinates = _local(world, pose(target))
                    geometry = context["geometries"][target]
                    if isinstance(geometry, ObservedField):
                        excluded = (() if permission is None or target != record["second"]
                                    else permission.excluded_second_cells)
                        signed, supported, direction = field_point_value(geometry, coordinates,
                                                                        excluded_cells=excluded)
                        value = -signed
                        if not supported:
                            mode = "unknown_target_support"
                    else:
                        value = -native_point_value(geometry, coordinates)
                        direction = True
            values.append(value + zero)
            reports.append({"row": ordinal, "mode": mode, "value": float(value.detach()),
                            "has_spatial_direction": direction})
        self.last_evaluation = {"rows": reports,
            "active_count": sum(row["mode"] == "active" for row in reports),
            "inactive_count": sum(row["mode"] != "active" for row in reports)}
        return torch.stack(values)

    def describe(self):
        """Return row provenance and actual query states for the planner report."""
        return {"scope": "necessary_original_material_constraints_with_complete_entity_oracle",
                "rows": [asdict(row) for row in self.witnesses],
                "discoveries": self.discoveries, "last_evaluation": self.last_evaluation}
